const CARD_VERSION='0.1.3';
const CARD_TAG='casambi-bt-card';
const EDITOR_TAG='casambi-bt-card-editor';
const BAD_SOURCES={android_bridge:['android_casambi_bridge'],jungle:['casambi_jungle','jungle'],hue:['hue_',' hue '],shelly:['shelly'],wallpanel:['wallpanel','wall_display'],helper:['helper']};
const DEFAULT_NEGATIVE=['android_casambi_bridge','casambi_jungle','hue_','shelly','helper','wallpanel','wall_display','rolladen'];
const stateName=s=>s?.attributes?.friendly_name||s?.entity_id||'';
const domainOf=e=>(e||'').split('.')[0];
const unavailable=s=>!s||['unavailable','unknown'].includes(s.state);
const normList=v=>!v?[]:Array.isArray(v)?v.filter(Boolean):String(v).split(/[\n,]/).map(x=>x.trim()).filter(Boolean);
const fire=(n,t,d)=>n.dispatchEvent(new CustomEvent(t,{detail:d,bubbles:true,composed:true}));
function slug(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ä/g,'a').replace(/ö/g,'o').replace(/ü/g,'u').replace(/ß/g,'ss').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');}
function rawData(hass,c){let ent=c.network_config_entity?hass.states[c.network_config_entity]:null;let list=ent?[ent]:Object.values(hass.states).filter(s=>domainOf(s.entity_id)==='sensor'&&s.attributes?.raw_network_data?.network);for(const s of list){if(s?.attributes?.raw_network_data?.network)return{raw:s.attributes.raw_network_data,entity:s.entity_id};}return{};}
function sourceOf(s){let eid=(s?.entity_id||'').toLowerCase(),fn=stateName(s).toLowerCase();for(const [src,words] of Object.entries(BAD_SOURCES)){if(words.some(w=>eid.includes(w)||fn.includes(w.replace(/_/g,' '))))return src;}return 'casambi_bt_candidate';}
function scoreEntity(s,wanted,network,type,c={}){if(!s)return-999;let eid=s.entity_id.toLowerCase(),fn=stateName(s),fl=fn.toLowerCase(),wl=String(wanted||'').toLowerCase(),ws=slug(wanted),ns=slug(network);let sc=0,reason=[];
 if(fn===wanted){sc+=100;reason.push('friendly exact');} if(fl===wl){sc+=90;reason.push('name exact');}
 if(network&&fl===`${network} ${wanted}`.toLowerCase()){sc+=95;reason.push('network name exact');}
 if(network&&fl===`${wanted} ${network}`.toLowerCase()){sc+=75;reason.push('unit network name');}
 if(ws&&eid.endsWith('_'+ws)){sc+=55;reason.push('entity suffix');} if(ws&&eid.includes(ws)){sc+=35;reason.push('entity contains unit slug');}
 if(ns&&eid.includes(ns)){sc+=25;reason.push('network slug');} if(!unavailable(s)){sc+=c.discovery?.prefer_available!==false?25:10;reason.push('available');}
 let src=sourceOf(s); if(DEFAULT_NEGATIVE.some(b=>eid.includes(b)||fl.includes(b.replace(/_/g,' ')))){sc-=100;reason.push('external source penalty');}
 if(type==='scene'&&ns&&ws&&eid===`scene.${ns}_${ws}`){sc+=130;reason.push('casambi scene pattern');}
 if(type==='light'&&ws&&eid.includes(ws)){sc+=30;reason.push('light name match');}
 return {score:sc,source:src,reason:reason.join(', ')||'weak match'};}
function rawTargets(hass,c,type){let {raw}=rawData(hass,c),net=c.network_name||raw?.network?.name||'';if(!raw?.network)return{targets:[],net};if(type==='light')return{targets:(raw.network.units||[]).map(u=>({name:u.name,id:u.deviceID||u.deviceId,uuid:u.uuid})).filter(x=>x.name),net};return{targets:(raw.network.scenes||[]).map(s=>({name:s.name,id:s.sceneID||s.sceneId})).filter(x=>x.name),net};}
function candidatesFor(hass,c,type){let dom=type==='light'?'light':'scene';let {targets,net}=rawTargets(hass,c,type);let cands=[];let all=Object.values(hass.states).filter(s=>domainOf(s.entity_id)===dom);let seen=new Map();
 for(const t of targets){for(const s of all){let r=scoreEntity(s,t.name,net,type,c);if(r.score>=35){let old=seen.get(s.entity_id);if(!old||r.score>old.score)seen.set(s.entity_id,{entity_id:s.entity_id,name:stateName(s),state:s.state,score:r.score,source:r.source,reason:r.reason,target:t.name,available:!unavailable(s)});}}}
 if(c.discovery?.include_fallback_candidates!==false){for(const s of all){let eid=s.entity_id.toLowerCase(),fn=stateName(s).toLowerCase();if((eid.includes('casambi')||fn.includes('casambi')||eid.includes(slug(net)))&&!seen.has(s.entity_id)){let r=scoreEntity(s,'',net,type,c);seen.set(s.entity_id,{entity_id:s.entity_id,name:stateName(s),state:s.state,score:r.score,source:r.source,reason:'fallback candidate',target:'fallback',available:!unavailable(s)});}}}
 cands=[...seen.values()].sort((a,b)=>b.score-a.score||a.name.localeCompare(b.name));return cands;}
function bestEntities(hass,c,type){let key=type==='light'?'lights':'scenes';let manual=normList(c[key]).filter(e=>hass.states[e]);if(manual.length)return manual;let list=candidatesFor(hass,c,type);let exclude=c.discovery?.exclude_sources||['android_bridge','jungle','hue','shelly','wallpanel','helper'];list=list.filter(x=>!exclude.includes(x.source));if(c.discovery?.hide_unavailable_duplicates!==false){let byName=new Map();for(const x of list){let k=slug(x.name);let old=byName.get(k);if(!old||(!old.available&&x.available)||x.score>old.score)byName.set(k,x);}list=[...byName.values()].sort((a,b)=>b.score-a.score);}if(c.discovery?.prefer_available!==false){list.sort((a,b)=>(b.available-a.available)||b.score-a.score);}return list.filter(x=>x.score>=70).map(x=>x.entity_id);}
function detectStatus(hass,c){if(c.status_entity&&hass.states[c.status_entity])return c.status_entity;let {raw}=rawData(hass,c),net=c.network_name||raw?.network?.name||c.title||'',ns=slug(net);let best,b=-999;Object.values(hass.states).filter(s=>domainOf(s.entity_id)==='binary_sensor').forEach(s=>{let eid=s.entity_id.toLowerCase(),fn=stateName(s).toLowerCase(),sc=0;if(ns&&eid===`binary_sensor.${ns}_status`)sc+=200;if(net&&fn===`${net} status`.toLowerCase())sc+=160;if(fn.includes('status'))sc+=25;if(DEFAULT_NEGATIVE.some(x=>eid.includes(x)))sc-=100;if(sc>b){b=sc;best=s;}});return b>=80?best.entity_id:undefined;}
class CasambiBtCard extends HTMLElement{static getConfigElement(){return document.createElement(EDITOR_TAG)}static getStubConfig(){return{title:'Casambi',style:'casambi',auto_discover:false,discovery:{prefer_available:true,hide_unavailable_duplicates:true},lights:[],scenes:[]}}setConfig(c){this._config={title:'Casambi',style:'casambi',auto_discover:false,discovery:{prefer_available:true,hide_unavailable_duplicates:true,exclude_sources:['android_bridge','jungle','hue','shelly','wallpanel','helper']},show_header:true,show_scenes:true,show_lights:true,show_footer:true,...c}}set hass(h){this._hass=h;this.render()}getCardSize(){return 4}async call(domain,service,data){await this._hass.callService(domain,service,data)}async scene(e){this._last=e;this._ts=Date.now();await this.call('scene','turn_on',{entity_id:e});this.render()}render(){if(!this._hass||!this._config)return;let h=this._hass,c=this._config,lights=bestEntities(h,c,'light'),scenes=bestEntities(h,c,'scene'),st=detectStatus(h,c),online=st?['on','connected','online','true'].includes(String(h.states[st]?.state).toLowerCase()):lights.some(e=>!unavailable(h.states[e]));let {raw,entity:cfg}=rawData(h,c),net=c.network_name||raw?.network?.name||c.title,active=lights.filter(e=>h.states[e]?.state==='on').length,off=lights.filter(e=>unavailable(h.states[e])).length;this.innerHTML=`<ha-card class="cb ${c.style}">${this.css()}${c.show_header!==false?`<div class="head"><div class="brand"><div class="logo">C</div><div><div class="title">${c.title}</div><div class="sub">${net||'Casambi'}</div></div></div><div class="state ${online?'on':'off'}"><i></i>${online?'Online':'Offline'}</div></div><div class="stats"><b>${lights.length}<span>Lichter</span></b><b>${active}<span>Aktiv</span></b><b>${scenes.length}<span>Szenen</span></b><b>${off}<span>Offline</span></b></div>`:''}${c.show_scenes!==false?`<h3><ha-icon icon="mdi:palette-outline"></ha-icon>Szenen</h3><div class="scenes">${scenes.length?scenes.map(e=>`<button data-scene="${e}"><ha-icon icon="mdi:creation"></ha-icon>${stateName(h.states[e]).replace(/^Casambi\s*/i,'')}</button>`).join(''):'<p>Keine Szenen gefunden. Wähle den Network Config Sensor oder öffne den Discovery-Assistenten.</p>'}</div>`:''}${c.show_lights!==false?`<h3><ha-icon icon="mdi:lightbulb-group-outline"></ha-icon>Lichter</h3><div class="grid">${lights.length?lights.map(e=>{let s=h.states[e],on=s?.state==='on',br=Number(s?.attributes?.brightness??(on?255:0));return`<div class="tile ${on?'on':''} ${unavailable(s)?'unav':''}"><div><strong>${stateName(s)}</strong><button data-toggle="${e}"><ha-icon icon="mdi:power"></ha-icon></button></div><small>${unavailable(s)?'Nicht verfügbar':on?'Ein':'Aus'}</small><input data-br="${e}" type="range" min="1" max="255" value="${Math.max(1,br)}"><em>${Math.round(br/2.55)}%</em></div>`}).join(''):'<p>Keine Lichter gefunden. Wähle den Network Config Sensor oder öffne den Discovery-Assistenten.</p>'}</div>`:''}<footer><span>Casambi BT Card ${CARD_VERSION}</span><span>${cfg||'Auto-Discovery per Network Config'}</span></footer></ha-card>`;this.querySelectorAll('[data-scene]').forEach(x=>x.onclick=()=>this.scene(x.dataset.scene));this.querySelectorAll('[data-toggle]').forEach(x=>x.onclick=()=>this.call('light','toggle',{entity_id:x.dataset.toggle}));this.querySelectorAll('[data-br]').forEach(x=>x.onchange=()=>this.call('light','turn_on',{entity_id:x.dataset.br,brightness:Number(x.value)}));}css(){return`<style>.cb{--a:#15c8ff;--b:#1de9b6;background:linear-gradient(145deg,#101827,#172437);color:var(--primary-text-color);border-radius:22px;overflow:hidden;padding:18px;border:1px solid rgba(255,255,255,.12)}.head{display:flex;justify-content:space-between;gap:12px}.brand{display:flex;gap:12px}.logo{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(135deg,var(--a),var(--b));color:#03202d;font-weight:900}.title{font-weight:800;font-size:18px}.sub,footer,small,p{color:var(--secondary-text-color);font-size:12px}.state{padding:8px 10px;border-radius:999px;background:rgba(255,255,255,.08);height:max-content}.state i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px;background:#ef5350}.state.on i{background:var(--b);box-shadow:0 0 10px var(--b)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0}.stats b{background:rgba(255,255,255,.08);border-radius:16px;padding:10px;text-align:center}.stats span{display:block;font-weight:400;color:var(--secondary-text-color);font-size:11px}h3{font-size:14px;display:flex;gap:8px;align-items:center}.scenes{display:flex;gap:9px;flex-wrap:wrap}.scenes button{border:1px solid rgba(255,255,255,.14);border-radius:999px;padding:10px 13px;background:rgba(255,255,255,.08);color:inherit;display:flex;gap:8px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:10px}.tile{background:rgba(255,255,255,.08);border-radius:18px;padding:12px}.tile.on{background:linear-gradient(145deg,rgba(21,200,255,.16),rgba(29,233,182,.1))}.tile.unav{opacity:.55}.tile div{display:flex;justify-content:space-between}.tile button{border:0;border-radius:13px;background:rgba(255,255,255,.12);color:inherit;width:36px;height:36px}.tile input{width:calc(100% - 48px);accent-color:var(--a)}.tile em{float:right;font-style:normal;font-size:12px}footer{display:flex;justify-content:space-between;margin-top:14px}.mushroom,.minimal{background:var(--ha-card-background,var(--card-background-color));box-shadow:none}.bubble{border-radius:32px}</style>`}}
class CasambiBtCardEditor extends HTMLElement{setConfig(c){this._config={auto_discover:false,style:'casambi',discovery:{prefer_available:true,hide_unavailable_duplicates:true,exclude_sources:['android_bridge','jungle','hue','shelly','wallpanel','helper']},...(c||{})};this._rendered=false;this.render()}set hass(h){this._hass=h;if(!this._rendered)this.render();else this.updatePickers()}updatePickers(){['status','networkConfig'].forEach(id=>{let p=this.querySelector('#'+id);if(p)p.hass=this._hass})}chg(k,v){this._config={...this._config,[k]:v};fire(this,'config-changed',{config:this._config});this.render()}setDiscovery(k,v){this._config={...this._config,discovery:{...(this._config.discovery||{}),[k]:v}};fire(this,'config-changed',{config:this._config});this.render()}applySelection(){let lights=[...this.querySelectorAll('input[data-kind="light"]:checked')].map(x=>x.value);let scenes=[...this.querySelectorAll('input[data-kind="scene"]:checked')].map(x=>x.value);this._config={...this._config,lights,scenes};fire(this,'config-changed',{config:this._config});this.render()}autoBest(){this._config={...this._config,lights:bestEntities(this._hass,this._config,'light'),scenes:bestEntities(this._hass,this._config,'scene')};fire(this,'config-changed',{config:this._config});this.render()}candHtml(type){let list=candidatesFor(this._hass,this._config,type);let selected=new Set(normList(this._config[type==='light'?'lights':'scenes']));if(!list.length)return'<p class="hint">Keine Kandidaten gefunden. Bitte Network Config Sensor setzen.</p>';return list.map(x=>`<label class="cand ${x.available?'ok':'bad'}"><input type="checkbox" data-kind="${type}" value="${x.entity_id}" ${selected.has(x.entity_id)||(!selected.size&&x.score>=90&&x.available)?'checked':''}><span><b>${x.name}</b><code>${x.entity_id}</code><small>Score ${x.score} · ${x.source} · ${x.available?'verfügbar':'unavailable'} · ${x.reason}</small></span></label>`).join('')}render(){if(!this._hass||!this._config)return;let c=this._config,d=c.discovery||{};this.innerHTML=`<div class="ed"><style>.ed{display:grid;gap:14px}.row{display:grid;gap:6px}input,select,textarea{width:100%;box-sizing:border-box;border:1px solid var(--divider-color);border-radius:10px;padding:9px;background:var(--card-background-color);color:var(--primary-text-color)}textarea{min-height:72px;font-family:monospace}.hint,small{font-size:12px;color:var(--secondary-text-color)}.box{border:1px solid var(--divider-color);border-radius:14px;padding:10px;display:grid;gap:8px}.cand{display:grid;grid-template-columns:24px 1fr;gap:8px;padding:8px;border-radius:12px;background:rgba(127,127,127,.1)}.cand.ok{border-left:3px solid #1de9b6}.cand.bad{opacity:.62;border-left:3px solid #ff6b6b}.cand b,.cand code,.cand small{display:block}.cand code{font-size:11px;color:var(--secondary-text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{border:0;border-radius:12px;padding:9px 12px;background:#03a9f4;color:white;font-weight:700}</style><div class="row"><label>Titel</label><input id="title" value="${c.title||'Casambi'}"></div><div class="row"><label>Stil</label><select id="style">${['casambi','mushroom','bubble','minimal'].map(s=>`<option ${c.style===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="row"><label>Status Entity optional</label><ha-entity-picker id="status" value="${c.status_entity||''}" allow-custom-entity></ha-entity-picker></div><div class="row"><label>Network Config Sensor empfohlen</label><ha-entity-picker id="networkConfig" value="${c.network_config_entity||''}" allow-custom-entity></ha-entity-picker><div class="hint">Empfohlen: sensor.kalli_network_configuration. Der Assistent nutzt raw_network_data.</div></div><div class="box"><b>Discovery-Assistent</b><label><input id="pref" type="checkbox" ${d.prefer_available!==false?'checked':''}> verfügbare Entities bevorzugen</label><label><input id="hide" type="checkbox" ${d.hide_unavailable_duplicates!==false?'checked':''}> unavailable Dubletten ausblenden</label><div class="actions"><button id="autoBest">Auto auswählen</button><button id="applySel">Auswahl übernehmen</button></div><b>Licht-Kandidaten</b>${this.candHtml('light')}<b>Szenen-Kandidaten</b>${this.candHtml('scene')}</div><div class="row"><label>Lichter manuell</label><textarea id="lights" placeholder="Leer lassen für Auto-Erkennung">${normList(c.lights).join('\n')}</textarea></div><div class="row"><label>Szenen manuell</label><textarea id="scenes" placeholder="Leer lassen für Auto-Erkennung">${normList(c.scenes).join('\n')}</textarea></div><label><input id="auto" type="checkbox" ${c.auto_discover!==false?'checked':''}> Fallback Auto-Discovery aktivieren</label></div>`;this.updatePickers();this.querySelector('#title').onchange=e=>this.chg('title',e.target.value);this.querySelector('#style').onchange=e=>this.chg('style',e.target.value);this.querySelector('#status').addEventListener('value-changed',e=>this.chg('status_entity',e.detail.value));this.querySelector('#networkConfig').addEventListener('value-changed',e=>this.chg('network_config_entity',e.detail.value));this.querySelector('#lights').onchange=e=>this.chg('lights',normList(e.target.value));this.querySelector('#scenes').onchange=e=>this.chg('scenes',normList(e.target.value));this.querySelector('#auto').onchange=e=>this.chg('auto_discover',e.target.checked);this.querySelector('#pref').onchange=e=>this.setDiscovery('prefer_available',e.target.checked);this.querySelector('#hide').onchange=e=>this.setDiscovery('hide_unavailable_duplicates',e.target.checked);this.querySelector('#applySel').onclick=()=>this.applySelection();this.querySelector('#autoBest').onclick=()=>this.autoBest();this._rendered=true}}
customElements.define(CARD_TAG,CasambiBtCard);customElements.define(EDITOR_TAG,CasambiBtCardEditor);window.customCards=window.customCards||[];window.customCards.push({type:CARD_TAG,name:'Casambi BT Card',description:'Casambi Bluetooth lights and scenes with assisted discovery'});console.info(`CASAMBI-BT-CARD ${CARD_VERSION}`);